import glob
import os
import re
import logging
import shutil
from robot.libraries.BuiltIn import BuiltIn
from taf.rfrl.utilities.robot.general import get_builtin_value
from taf.rfrl.utilities.transfer_files import download_files
from taf.rfrl.ue.parsers.iperf_report_parser import IperfReportParser
from ute_ue.utils.param_checker import tput_user_value2normalized


class ThroughputValidation(object):
    def __init__(self, ues_configuration=None):
        if ues_configuration:
            self.ues_configuration = ues_configuration
        else:
            self.ues_configuration = {"all_ues": [0]}
        self.params = None
        self.exceptions = []
        self.current_dt_results = {}
        self.data_transfer_params = None

    def validate_current_throughput_values(self, transfers_to_validate, dl_tput=None, ul_tput=None, tolerance=None):
        """
        Validation of last data transfers throughput results based on provided parameters.
        e.g. validate_actual_throughput_values(transfers_to_validate="2", dl_tput="300M", ul_tput="100M")

        :param transfers_to_validate:   number of all transfer which should be validated
        :type transfers_to_validate:    str
        :param dl_tput:                 target DL throughput value. If dl_tput=None DL data transfer won't be validated
        :type dl_tput:                  str
        :param ul_tput:                 target UL throughput value. If ul_tput=None UL data transfer won't be validated
        :type ul_tput:                  str
        :param tolerance:               percent tolerance value of target throughput. If tolerance=None every value
                                        above target will be accepted
        :type tolerance:                str
        :return:                        None
        """
        dt_names = self.current_dt_results.keys()
        if int(transfers_to_validate) == len(dt_names):
            logging.info("All transfers end with success")
        else:
            logging.error("Some transfers end with failure")
        for dt in dt_names:
            BuiltIn().log_to_console("\n----------------{}----------------".format(dt))
            if dl_tput and "DL" in dt:
                self._validate_dt_throughput_value(dt, dl_tput, tolerance)
            elif ul_tput and "UL" in dt:
                self._validate_dt_throughput_value(dt, ul_tput, tolerance)
            else:
                continue
        self.current_dt_results = {}
        self._check_execution_exceptions()

    def get_data_transfers_results(self):
        self._download_all_iperf_reports()
        self._analyse_iperf_reports()

    def _validate_dt_throughput_value(self, dt_name, tput_value, tolerance):
        _re_expected_data_size = r'(?P<VALUE>\d*)(?P<UNIT>K|M|G)'
        expected_data_size = re.search(_re_expected_data_size, tput_value)
        _re_data_size = r'(?P<VALUE>(\d|.)+)(?P<UNIT>K|M|G)bits/sec'
        current_data_size = re.search(_re_data_size, self.current_dt_results[dt_name])
        ue_serial_number = dt_name.split("_")[0]
        if not self.current_dt_results[dt_name]:
            logging.error(
                "Connection issue occurred during DT {}. Check connectivity between client and server".format(dt_name))
            self.exceptions.append(ConnectionErrorBetweenClientAndServer)
        BuiltIn().log_to_console("Average throughput value with UE {} = {}"
                                 .format(ue_serial_number, self.current_dt_results[dt_name]))
        BuiltIn().log_to_console("Target average throughput value = {}bits/sec".format(tput_value))
        expected_tput_value = tput_user_value2normalized(expected_data_size.group('VALUE')
                                                         + expected_data_size.group("UNIT") + "bits/sec")
        current_tput_value = tput_user_value2normalized(current_data_size.group('VALUE')
                                                        + current_data_size.group("UNIT") + "bits/sec")
        if tolerance:
            max_tput = expected_tput_value + expected_tput_value * int(tolerance.replace("%", "")) / 100
            min_tput = expected_tput_value - expected_tput_value * int(tolerance.replace("%", "")) / 100
            if min_tput <= current_tput_value <= max_tput:
                logging.info("Throughput value of DT {} is correct".format(dt_name))
            else:
                logging.error("{} throughput value does NOT meet tolerance criteria. Check iperf logs --> {}".format(
                    ue_serial_number, self._get_iperf_reports_path()))
                self.exceptions.append(IncorrectThroughputValue)
        else:
            if expected_tput_value <= current_tput_value:
                logging.info("Throughput value of DT {} is correct".format(dt_name))
            else:
                logging.error("{} throughput value is lower than target value. Check iperf logs --> {}".format(
                    ue_serial_number, self._get_iperf_reports_path()))
                self.exceptions.append(IncorrectThroughputValue)

    def _download_all_iperf_reports(self):
        for ue_id in self.ues_configuration["all_ues"]:
            download_files(local_dir="/tmp", remote_file="*moler_iperf.txt", device_name="UE{}_PC".format(ue_id),
                           remote_dir="/tmp", from_state="UNIX_REMOTE", remove_source_file=True, log_level='info')
            download_files(local_dir="/tmp", remote_file="*moler_iperf.txt", device_name="APP_SERVER{}".format(ue_id),
                           remote_dir="/tmp", from_state="UNIX_REMOTE", remove_source_file=True, log_level='info')

    def _analyse_iperf_reports(self):
        for report_file in glob.glob(r"/tmp/*moler_iperf.txt"):
            try:
                avg = IperfReportParser(report_file).parse_report()["avg"]
                dt_name = report_file.split("/")[-1].replace("moler_iperf.txt", "")
                self.current_dt_results.update({dt_name: avg})
            except Exception as e:
                logging.warning("{} -> {}".format(report_file, e))
                self.exceptions.append(ConnectionErrorBetweenClientAndServer)
            finally:
                shutil.move(report_file, self._get_iperf_reports_path())
        self._check_execution_exceptions()

    def _check_execution_exceptions(self):
        recent_exceptions = self.exceptions
        self.exceptions = []
        if recent_exceptions:
            logging.error("Following exceptions occurred during actual data transfers:")
            raise Exception(recent_exceptions)

    @staticmethod
    def _get_iperf_reports_path():
        if not os.path.exists(os.path.join(get_builtin_value('OUTPUT_DIR'), "IPERF_REPORTS")):
            os.mkdir(os.path.join(get_builtin_value('OUTPUT_DIR'), "IPERF_REPORTS"))
        return os.path.join(get_builtin_value('OUTPUT_DIR'), "IPERF_REPORTS")


class NoAvailableUesException(Exception):
    pass


class IncorrectThroughputValue(Exception):
    pass


class ConnectionErrorBetweenClientAndServer(Exception):
    pass


class UnknownUeType(Exception):
    pass
